/**
 * emit to subscription queries of type FindExchangeRate,
 * but only if the id matches
 *
 * @param		entity	ExchangeRate
 */
	protected void emitFindExchangeRate( ExchangeRate entity ) {
		LOGGER.info("handling emitFindExchangeRate" );
		
	    queryUpdateEmitter.emit(FindExchangeRateQuery.class,
	                            query -> query.getFilter().getExchangeRateId().equals(entity.getExchangeRateId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllExchangeRate
	 * 
	 * @param		entity	ExchangeRate
	 */
	protected void emitFindAllExchangeRate( ExchangeRate entity ) {
		LOGGER.info("handling emitFindAllExchangeRate" );
		
	    queryUpdateEmitter.emit(FindAllExchangeRateQuery.class,
	                            query -> true,
	                            entity);
	}

